import {fork} from 'node:child_process';
import {mkdtempSync,rmSync,writeFileSync} from 'node:fs';
import {tmpdir,cpus,totalmem} from 'node:os';
import {join,resolve} from 'node:path';
import {SQLiteRepository} from '../../src/persistence/sqlite.ts';
import {Tracer} from '../../src/index.ts';
const provenance={actor:'concurrent-local-audit'};
if(process.argv[2]==='worker') {
 const repository=new SQLiteRepository(process.argv[3]);
 process.send({event:'ready'});
 process.on('message',async message=>{
  if(message==='hold') {
   await repository.transaction(async tx=>{
    await tx.headRevision();
    process.send({event:'held'});
    await new Promise(resolve=>process.once('message',resolve));
   });
   repository.close();process.disconnect();
  }
 });
} else {
 const dir=mkdtempSync(join(tmpdir(),'tracer-concurrency-audit-'));
 const database=join(dir,'project.sqlite');
 const repository=new SQLiteRepository(database),tracer=new Tracer(repository);
 await tracer.setSchema({entityTypes:{item:{fields:{}}},relationshipTypes:{}},0,provenance);
 const child=fork(resolve('output/concurrent-local/lock-probe.mjs'),['worker',database],{stdio:['ignore','ignore','pipe','ipc']});
 const wait=event=>new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(new Error('worker timeout '+event)),5000);const listener=message=>{if(message.event===event){clearTimeout(timeout);child.off('message',listener);resolve();}};child.on('message',listener);});
 try {
  await wait('ready');const held=wait('held');child.send('hold');await held;
  const start=performance.now();let result;
  try{await tracer.getSchema();result={outcome:'success'};}catch(error){result={outcome:'rejected',code:error.code,message:error.message};}
  result.durationMs=performance.now()-start;
  child.send('release');await new Promise(resolve=>child.once('exit',resolve));
  const recovered=(await tracer.getSchema()).version;
  const report={candidate:'fb0c32323765bce221d5c42e52f8781df3bdcae3',environment:{node:process.version,platform:process.platform,arch:process.arch,cpu:cpus()[0]?.model,memoryBytes:totalmem()},procedure:'Independent process holds a repository transaction after a native head read; already-open parent repository attempts a public schema read. No writes occur inside held transaction.',result,recoveredSchemaVersion:recovered,interpretation:'BEGIN IMMEDIATE reserves the SQLite writer slot for all reads. This probe tests read/read contention, not lost updates or authenticated team behavior.'};
  writeFileSync('output/concurrent-local/lock-probe-result.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(report));
 } finally {child.kill();repository.close();rmSync(dir,{recursive:true,force:true});}
}

